namespace Shop
{
    public static class Pricing
    {
        public static decimal Price(decimal amount)
        {
            return amount;
        }

        public static decimal Price(decimal amount, int qty)
        {
            return amount * qty;
        }

        public static decimal Discount(decimal amount)
        {
            return amount * 0.9m;
        }
    }
}

A.Checkout.cs:
namespace Shop
{
    public static class Checkout
    {
        public static decimal Run(decimal[] amounts, int[] qtys)
        {
            decimal total = 0;
            for (var i = 0; i < amounts.Length; i++)
            {
                total += Pricing.Price(amounts[i], qtys[i]);
            }
            return Pricing.Discount(total);
        }
    }
}

